import React from 'react';
import Header from '../Header';
import './Itempage.css';
import Footer from '../Footer';
import saree1 from './saree1.jpg';
import saree2 from './saree2.jpg';
import saree3 from './saree3.jpg';
import saree4 from './saree4.jpg';

const ItemPage = () => {

    
    const saree = {
        name: "Traditional Silk Saree",
        price: "₹4,500",
        description: "A beautiful traditional silk saree, perfect for weddings and festive occasions.",
    };

    const handleAddToCart = () => {
        setMessage(`🌟 ${quantity} ${saree.name} added to cart! 🌟`);
        setTimeout(() => {
            setMessage('');
        }, 3000);
    };

    return (
        <div className="item-page">
            <div className="image-container">
                <img src={saree1} alt={saree.name} />
                <div className='sub-images-container'>
                    <img src={saree2}></img>
                    <img src={saree3}></img>
                </div>
            </div>
            <div className="details-container">
                <h1 className="item-name">{saree.name}</h1>
                <p className="item-price">{saree.price}</p>
                <p className="item-description">{saree.description}</p>
                <div className="quantity-container">
                    <label htmlFor="quantity">Quantity: </label>
                    <input type="number" id="quantity" min="1" value={quantity} onChange={(e) => setQuantity(e.target.value)}
                    />
                </div>
                <button className="add-to-cart-button">Add to Cart</button>
            </div>
        </div>
    );
};

export default ItemPage;
